INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N046-01','CN0068','S046-01','设计分股与投资','3.10-5/6、3.11.2、6.7-1','清洗活化九股44821.46m³/a；站200m³/d，进站168.04m³/d；表3.13-20 50512.76m³/a、产水15153.83、浓水35358.93（30/70%），接管合计41143.46。污水站概算200万元、环保462万元、总投资5000万元分别；非实际成本。联合建设单位广东青骐骥。年日值不强换算。','WEB_PRIMARY','公开正文摘录；PDF截图失败/未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N046-02','CN0068','S046-01','工艺与报告矛盾','3.11、图3.11-2、表3.13-20/21、环保措施表','活化独立中和混凝絮凝沉淀，物理/化学清洗预处理，合流电催化氧化、电絮凝沉淀、二级RO；滤液回收集池2。水质表另写UF+RO，不能确认UF设备；表3.13-20重金属列名重复与错位，仅录可靠前三指标；表3.13-21综合13指标清楚。生活回用与纳管叙述冲突、污泥一般/危废表述冲突、初雨6.21/9.84m³/d不同、事故池600/850m³异文；暂不判定建成。接管须有重金属排放指标。截图超限。','WEB_PRIMARY','公开正文摘录；PDF截图失败/未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N046-03','CN0069','S046-02','既有站及验收','3.1.1、表3.1-2/5/6/10/11','2019一期与2022-04二期自主验收历史；一期再生二期处置各5000m³/a不重复。150m³/d设施与批复一致；报告列废ED+RO膜0.05t/a、污泥110、蒸馏残渣32t/a，非水量。生产水回用、生活因管网未铺设拉运；2160m³/a生活核算及2022八次五项生活排口监测。原文三期水平衡涉删节，未猜数据；截图404。','WEB_PRIMARY','公开正文摘录；PDF截图失败/未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N046-04','CN0043','S046-03','高盐废水和原线边界','3.7.2、表3.7-4/5、3.9-1','封面2019-01，不能用网站新上传时间当报告年份。回收废水盐100000/TN15700mg/L，富集体分离盐50000，酸洗塔TN42600，均历史核算；三效冷凝回喷淋清洗，废盐残渣390t/a为报告固废量。正文热处理尾气碱洗塔同时列蒸发和接管，按表3.7-4 6000m³/a接管并保留冲突。纯水/软水与冷却清下水另列；废RO膜未证污水膜，园区膜不归本厂；一期实际列9643.2t/a与工程表m³/a不强换算。2018两日接管与清下水监测。截图超时。','WEB_PRIMARY','公开正文摘录；PDF截图失败/未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N046-05','CN0130','S046-04','浙江综合验收','2023年年度报告经营情况','报告称浙江长兴子公司报告期内完成综合验收并投产，非独立环保验收文件；未披露废水设备细节，仍保留首图缺口。','WEB_COMPANY','公开正文摘录；PDF截图失败/未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N046-06','CN0303','S046-04','江西历史投运','2023年年度报告经营情况','江西凯大2017-07-21投产历史，公司当时称平稳运行及危废许可延续，证号环危废证字104号；2026转让不据此推定现行在产。','WEB_COMPANY','公开正文摘录；PDF截图失败/未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N046-07','CN0125','S046-05','2024运行自述','年报环保段','新剂清洗水浓缩到一定浓度回混炼；再生喷淋/鼓泡/超声/酸浸水处理后回喷淋；生活化粪池→蔡田铺污水厂。更新2024自述，未给具体站量、膜型与成本，不重复旧工艺事实。','WEB_COMPANY','公开正文摘录；PDF截图失败/未归档原件','2026-11-28');
