INSERT INTO membrane_retrofits (assessment_id,review_id,site_id,scope_key,option_key,revision,objective,proposed_route,feasibility,hard_constraints,evidence_basis,assumptions,missing_inputs,validation_plan,alternatives,feed_risk,pretreatment_risk,concentrate_risk,integration_risk,operational_risk,compliance_economics_risk,score_basis,updated_on) VALUES ('RA046-01','R046-01','CN0068','regeneration-design','screening',2,'分质回用与能耗优化','优先核实际建设与重金属指标；既设计两级RO，不推重复设备；若仅30%回用且浓水纳管可用，先以硬度、硅、盐种和重金属平衡评估提高回收率及UF预处理；比较电耗、电极、膜清洗与浓水费用。','conditional','金属回收、浓水合法去向、现行投运及水质需核','INFERRED；S046-01；2024环评设计，非建成；UF及生活/污泥异文见摘要','非已建新增设备','实际批复、投运、盐种及浓水指标、运行费','分股采样、预处理小试、盐金属衡算、膜试验、同边界生命周期成本','原工艺维持、源头减量和蒸发回收',NULL,NULL,NULL,NULL,NULL,NULL,'六维现场参数不全，难度未知','2026-11-28');
